// 1. Force pull from Trigger to avoid data loss from intermediate nodes (like CONFIG)
let triggerData;
try {
  triggerData = $('TRIGGER_NODE').first().json;
} catch (e) {
  triggerData = $input.first().json;
}

const body = triggerData.body || triggerData;

// 2. Noise Detection (Resend IDs, Webhook events)
const isResendNoise = (obj) => {
  if (obj.id && String(obj.id).startsWith('re_')) return true;
  if (obj.type && String(obj.type).startsWith('email.')) return true;
  return false;
};

if (isResendNoise(body)) {
  console.log("Ignored: Resend ID or Tracking Event.");
  return []; 
}

// 3. Deep Search for site_web/nom
const findValue = (obj, targetKey) => {
  if (!obj || typeof obj !== 'object') return null;
  const keys = Object.keys(obj);
  const foundKey = keys.find(k => k.toLowerCase() === targetKey.toLowerCase());
  if (foundKey) return obj[foundKey];
  for (const key of keys) {
    if (typeof obj[key] === 'object') {
      const res = findValue(obj[key], targetKey);
      if (res) return res;
    }
  }
  return null;
};

const raw_nom = findValue(body, "nom") || findValue(body, "name");
const raw_site = findValue(body, "site_web") || findValue(body, "url") || findValue(body, "website");
const raw_secteur = findValue(body, "secteur") || findValue(body, "industry") || findValue(body, "category");
const raw_ville = findValue(body, "ville") || findValue(body, "city") || findValue(body, "location");

if (!raw_site) {
  console.log("No site_web found in trigger payload:", JSON.stringify(body));
  return []; 
}

let url = String(raw_site).trim();
if (!url.startsWith("http")) url = "https://" + url;
url = url.replace(/\/$/, "");

let nom = raw_nom ? String(raw_nom).trim() : "";
if (!nom) {
  try { nom = new URL(url).hostname.split('.')[0]; } catch(e) { nom = "Prospect Inconnu"; }
}

return [{ json: { 
  nom,
  site_web: url,
  secteur: (raw_secteur || "autre").toLowerCase().trim(),
  ville: (raw_ville || "France").trim(),
  email: findValue(body, "email") || null,
  pipeline_id: triggerData.pipeline_id || ("gn_"+Date.now()+"_"+Math.random().toString(36).substr(2,6)),
  started_at: new Date().toISOString(),
  retry_state: { stratege: 0, architecte: 0, copywriter: 0, max: 2 }
} }];

const prospect = $("INIT_NODE").first().json;
const scan = $input.first().json;
const BLACKLIST = ["facebook.com","amazon.","google.com","apple.com","microsoft.com","booking.com","tripadvisor"];
if (!scan.status || scan.status >= 400) return [{ json: { brain_go: false, brain_reason: "Site inaccessible HTTP "+scan.status, prospect, scan } }];
if (!scan.ttfb || scan.ttfb > 9000) return [{ json: { brain_go: false, brain_reason: "TTFB mort ou absent", prospect, scan } }];
try { const host = new URL(prospect.site_web).hostname; if (BLACKLIST.some(b => host.includes(b))) return [{ json: { brain_go: false, brain_reason: "Blackliste", prospect, scan } }]; } catch(e) {}
const brain_context = JSON.stringify({ prospect: { nom: prospect.nom, site: prospect.site_web, secteur: prospect.secteur, ville: prospect.ville }, signals: { ttfb_ms: scan.ttfb, http_status: scan.status, title: scan.title || "ABSENT", h1: scan.h1 || "ABSENT", meta_desc: scan.meta_desc ? "presente ("+scan.meta_desc.length+" chars)" : "ABSENTE" } });
return [{ json: { brain_go: true, brain_context, prospect, scan, retry_state: prospect.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let parsed;
try { parsed = JSON.parse(clean); } catch(e) { parsed = { decision:"GO", confidence:50, top_angles:["Performance","SEO Local"], probleme_critique:"Site non optimise", ton_optimal:"consultant_expert", brain_reasoning:"Fallback", priorite:"moyenne", seuil_qualite_minimum:65, agent_instructions:{stratege:"Focus ROI",architecte:"Mobile-first",copywriter:"Direct"} }; }
return [{ json: { brain_decision_1: parsed, brain_go: parsed.decision==="GO", prospect: $("PRE_ANALYSE_NODE").first().json.prospect, scan: $("PRE_ANALYSE_NODE").first().json.scan, retry_state: $("INIT_NODE").first().json.retry_state } }];

const all = $input.all();
const scan = all.find(i => i.json.full_text || i.json.design_tokens)?.json || {};
const lh = all.find(i => i.json.performanceScore !== undefined)?.json || {};
return [{ json: { scan_full: scan, lighthouse: lh } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const extractJson = (str) => {
  try {
    const clean = str.replace(/```json\n?/g,"").replace(/```/g,"").trim();
    const first = clean.indexOf('{');
    const last = clean.lastIndexOf('}');
    if (first === -1) return null;
    return JSON.parse(clean.substring(first, last + 1));
  } catch(e) { return null; }
};
let parsed = extractJson(text);
if (!parsed) { 
  parsed = { 
    decision_finale: "GO", 
    ca_perdu_estime: "800€ - 1500€/mois est.", 
    hook_principal: "Votre site perd des clients chaque jour", 
    brain_synthesis: "Audit critique: Plusieurs alertes bloquantes détectées.", 
    score_opportunite: 75, 
    next_action: "email_immediat", 
    instructions_stratege: "Focus ROI", 
    instructions_architecte: "Mobile-first", 
    instructions_copywriter: "Direct"
  }; 
}
return [{ json: { brain_final: parsed, brain_go_final: (parsed.decision_finale || parsed.decision)==="GO", prospect: $("INIT_NODE").first().json, audit: $("AUDIT_ULTRA_NODE").first().json, brain_decision_1: $("PARSE_DECISION_1_NODE").first().json.brain_decision_1, retry_state: $("INIT_NODE").first().json.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let ev;
try { ev = JSON.parse(clean); } catch(e) { ev = { verdict:"APPROVE", score:70, raisons:[], instruction_retry:"" }; }
const prev = $("PARSE_PLAN_FINAL_NODE").first().json;
const rc = prev.retry_state?.stratege ?? 0;
const approved = ev.verdict==="APPROVE" || rc >= (prev.retry_state?.max ?? 2);
return [{ json: { stratege_output: $("STRATEGE_NODE").first().json, stratege_eval: ev, stratege_approved: approved, stratege_retry_instruction: ev.instruction_retry, retry_state: { ...prev.retry_state, stratege: rc+1 }, brain_final: prev.brain_final, brain_decision_1: prev.brain_decision_1, prospect: prev.prospect, audit: prev.audit } }];

const d = $input.first().json;
const stratege_final = d.stratege_output || d;
return [{ json: { stratege_final, brain_final: $("PARSE_PLAN_FINAL_NODE").first().json.brain_final, brain_decision_1: $("PARSE_PLAN_FINAL_NODE").first().json.brain_decision_1, prospect: $("PARSE_PLAN_FINAL_NODE").first().json.prospect, audit: $("PARSE_PLAN_FINAL_NODE").first().json.audit, retry_state: $("PARSE_EVAL_STRATEGE_NODE").first().json.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let ev;
try { ev = JSON.parse(clean); } catch(e) { ev = { verdict:"APPROVE", score:70, raisons:[], instruction_retry:"" }; }
const prev = $("BEST_STRATEGE_NODE").first().json;
const rc = prev.retry_state?.architecte ?? 0;
const approved = ev.verdict==="APPROVE" || rc >= (prev.retry_state?.max ?? 2);
return [{ json: { architecte_output: $("ARCHITECTE_NODE").first().json, architecte_eval: ev, architecte_approved: approved, architecte_retry_instruction: ev.instruction_retry, stratege_final: prev.stratege_final, retry_state: { ...prev.retry_state, architecte: rc+1 }, brain_final: prev.brain_final, brain_decision_1: prev.brain_decision_1, prospect: prev.prospect, audit: prev.audit } }];

const d = $input.first().json;
const archi_final = d.architecte_output || d;
return [{ json: { archi_final, stratege_final: $("PARSE_EVAL_ARCHITECTE_NODE").first().json.stratege_final, brain_final: $("PARSE_PLAN_FINAL_NODE").first().json.brain_final, brain_decision_1: $("PARSE_PLAN_FINAL_NODE").first().json.brain_decision_1, prospect: $("PARSE_PLAN_FINAL_NODE").first().json.prospect, audit: $("PARSE_PLAN_FINAL_NODE").first().json.audit, retry_state: $("PARSE_EVAL_ARCHITECTE_NODE").first().json.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let ev;
try { ev = JSON.parse(clean); } catch(e) { const copy = $("COPYWRITER_NODE").first().json; ev = { verdict:"APPROVE", qualite_score:65, envoyable:true, raisons_rejet:[], objet_final: copy.objet||copy.variante_a?.objet||"", corps_final: copy.corps||copy.variante_a?.corps||"", brain_note:"Fallback", instruction_retry:"" }; }

// Détection d'Opt-out robuste
const hasOptOut = /opt-out|désinscription|desinscription|ne plus recevoir|stop/i.test(ev.corps_final);
if (ev.corps_final && !hasOptOut) { 
  ev.corps_final += "\n\n---\nSi vous ne souhaitez plus recevoir ce type d analyses, repondez simplement Opt-out."; 
}

const prev = $("BEST_ARCHITECTE_NODE").first().json;
const rc = prev.retry_state?.copywriter ?? 0;
const approved = (ev.verdict==="APPROVE" || rc >= (prev.retry_state?.max ?? 2)) && ev.envoyable && ev.qualite_score >= 60;
return [{ json: { copywriter_eval: ev, copywriter_approved: approved, copywriter_retry_instruction: ev.instruction_retry, retry_state: { ...prev.retry_state, copywriter: rc+1 }, brain_final: prev.brain_final, brain_decision_1: prev.brain_decision_1, prospect: prev.prospect, audit: prev.audit, stratege_final: prev.stratege_final, archi_final: prev.archi_final } }];

const get = (node) => { try { return $(node).first().json; } catch(e) { return {}; } };
const audit = get("AUDIT_ULTRA_NODE");
const decision = get("PARSE_DECISION_1_NODE");
const brain = get("PARSE_PLAN_FINAL_NODE");
const stratege = get("BEST_STRATEGE_NODE");
const archi = get("BEST_ARCHITECTE_NODE");
const copyEval = get("PARSE_CRITIQUE_FINAL_NODE");
const init = get("INIT_NODE");

const finalQualif = {
  score_global: audit.score_global || decision.brain_decision_1?.score_global || brain.brain_final?.score_opportunite || 0,
  priorite: decision.brain_decision_1?.priorite || "MOYENNE",
  raison: brain.brain_final?.brain_synthesis || audit.verdict || "Analyse terminée",
  scores: decision.brain_decision_1?.scores || audit.qualification?.scores || {}
};

return [{ json: { 
  nom: init.nom || "Prospect", 
  site_web: init.site_web, 
  secteur: init.secteur || "autre", 
  ville: init.ville || "France", 
  email: init.email || null, 
  score_opportunite: finalQualif.score_global, 
  score_qualite_email: copyEval.qualite_score || 0, 
  email_objet: copyEval.objet_final || "", 
  email_body: copyEval.corps_final || "", 
  brain_synthesis: finalQualif.raison, 
  brain_ca_perdu: audit.estimation_impact?.ca_non_capte_estime || "Calculé", 
  status: init.email ? "email_ready" : "no_email",
  audit_data: { 
    ...audit,
    analyse_piliers: audit.analyse_piliers || {},
    estimation_impact: audit.estimation_impact || {},
    qualification: finalQualif,
    brain_final: brain.brain_final 
  },
  proposition_data: {
    strategy: stratege.stratege_final || stratege,
    architecture: archi.archi_final || archi
  }
} }];
